{"code":"import random

def generate(rng):
    # 8x8 sparse grids containing a compact nonzero pattern near the upper-left;
    # use a small rectangular motif, as in the example.
    g = [[0]*8 for _ in range(8)]
    h = rng.randint(2, 4)
    w = rng.randint(2, 4)
    r0 = rng.randint(0, 1)
    c0 = rng.randint(0, 2)
    color = rng.randint(1, 9)
    # generate a connected-ish motif with at least one cell in every row
    for r in range(h):
        for c in range(w):
            if rng.random() < 0.65 or (c == 0 and r == 0):
                g[r0+r][c0+c] = color
    return g"}

